            pstate, traces);
        }
        if (String_Constant* str = Cast<String_Constant>(exp)) {
          str->quote_mark(0);
        }
        std::string exp_src = exp->to_string();
        SelectorListObj sel = Parser::parse_selector(exp_src.c_str(), ctx, traces,
                                                     exp->pstate(), pstate.src,
                                                     /*allow_parent=*/true);

        for (auto& complex : sel->elements()) {
          if (complex->empty()) {
